import{_ as a}from"./chunks/architecture.DdIdPF_l.js";import{_ as t,o as i,c as s,a6 as o}from"./chunks/framework.CKIbuWFA.js";const b=JSON.parse('{"title":"应用与服务架构","description":"","frontmatter":{"title":"应用与服务架构","docId":"developer.architecture","translationKey":"developer.architecture","locale":"zh","audience":"developer","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"00ea88ebd11714484d717b7d7533d29158afd498121db362a3d300bc21889501","translationRevision":"b93fd0c6b6557305c77b346b2245d41c078d2b4d8e692936f6bb1eea06fed1db","order":30},"headers":[],"relativePath":"zh/developer/architecture.md","filePath":"zh/developer/architecture.md","lastUpdated":1794611623000}'),r={name:"zh/developer/architecture.md"};function c(d,e,l,n,p,h){return i(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="application-and-service-architecture" tabindex="-1">应用与服务架构 <a class="header-anchor" href="#application-and-service-architecture" aria-label="Permalink to &quot;应用与服务架构 {#application-and-service-architecture}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">目标与前置条件 <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;目标与前置条件 {#goal-and-prerequisites}&quot;">​</a></h2><p>将改动放在拥有对应状态的服务中。先阅读<a href="./setup.html">环境设置</a>，并理解现有宿主与明确创建的独立宿主有何区别。桌面构建一个 <code>AppCore</code>，用一个 <code>ControlApi</code> 包装它，再向 WebView、本地 CLI 及代理公开该实例。</p><h2 id="trace-an-operation" tabindex="-1">跟踪一次操作 <a class="header-anchor" href="#trace-an-operation" aria-label="Permalink to &quot;跟踪一次操作 {#trace-an-operation}&quot;">​</a></h2><ol><li>在 <code>crates/tiktools-control-api/src/modules/</code> 中找到方法注册。注册提供 schema、策略及发现元数据。</li><li>沿处理器进入 <code>crates/tiktools-core/src/control/</code> 及所属服务。领域验证和持久化修改应放在这里，不应放在传输适配器中。</li><li>在 <code>crates/tiktools-client</code> 添加类型化包装；其对等测试会比较 SDK 覆盖与注册的接口。</li><li>通过 <code>src/web/shared/api/control-client.ts</code> 使用该方法。Vue entity 管理展示状态；桌面不会把数据库或原生集成对象交给 WebView。</li></ol><p>Winit 管理事件循环，Wry 管理 WebView，托盘集成管理托盘。<code>HostEmitter</code> 和领域事件将序列化值从核心传出。桌面通过事件循环代理转发工作；WebView 脚本求值仍在该线程执行。Tokio 运行异步宿主操作。</p><h2 id="concrete-boundary-check" tabindex="-1">具体边界检查 <a class="header-anchor" href="#concrete-boundary-check" aria-label="Permalink to &quot;具体边界检查 {#concrete-boundary-check}&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> control-client</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rust</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tiktools-client</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> parity</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --locked</span></span></code></pre></div><p>第一条命令检查前端客户端。第二条在保留锁文件的前提下直接运行 SDK 集成测试目标；Cargo 目标参数应使用 <code>rust</code> 透传，而非更窄的针对性测试语法。</p><h2 id="expected-result-and-status" tabindex="-1">预期结果与状态 <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;预期结果与状态 {#expected-result-and-status}&quot;">​</a></h2><p>所有客户端观察相同的权威操作和事件路径。<code>host --ipc</code>、<code>host --stdio</code> 和 <code>--standalone</code> 会有意创建无界面所有者；普通 CLI 命令附加到运行中的所有者。旧 <code>PageMessage</code>/<code>IpcRouter</code> 路径仅保留为兼容代码，不应新增消息变体。</p><h2 id="recovery" tabindex="-1">恢复方法 <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;恢复方法 {#recovery}&quot;">​</a></h2><p>两个客户端结果不一致时，先比较宿主身份、主目录、构建功能及发现结果，再考虑添加其他 store。缺少插件是运行时目录问题，不应因此将其实现编译进核心。历史架构文档含有已退役的前端路径；有分歧时，以<a href="https://github.com/nglmercer/TikTools-app/blob/remake/crates/tiktools-core/src/lib.rs" target="_blank" rel="noreferrer">当前核心</a>及<a href="./frontend.html">前端结构</a>为准。</p><p><img src="`+a+'" alt="TikTools AppCore、传输、ControlClient 与真实 Vue 工作区"></p><h2 id="operational-details" tabindex="-1">运行细节 <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;运行细节 {#operational-details}&quot;">​</a></h2><p>所选二进制的 Cargo features 决定编译的路径。核心默认启用 <code>native-plugins</code> 与 <code>napi-vm-node-api</code>；<code>persistence</code> 提供 SQLite，<code>native-tiktok</code> 提供 LIVE 适配器/入口，<code>plugin-install</code>、<code>cloud-auth</code>、<code>app-update</code> 分别增加相关服务。先检查 <code>cargo tree -p tiktools-desktop -e features</code>（或实际 CLI 目标），再检查运行时 <code>system.info</code>/discovery。编译支持不等于服务已配置可用。使用<a href="./performance.html">性能指南</a>中的 <code>native-tiktok</code> 回归明确测试 LIVE 入口。</p>',16)])])}const F=t(r,[["render",c]]);export{b as __pageData,F as default};
